import pathlib,json,hashlib,time,datetime,re
L=pathlib.Path(__file__).resolve().parent;t=time.monotonic(); reads=[]
def sha(b):return hashlib.sha256(b).hexdigest()
def read(p):
 p=pathlib.Path(p);assert not any(w in str(p).lower() for w in ['crown','transitive-bunkbed-formal-pi-r2']);b=p.read_bytes();reads.append({'path':str(p),'bytes':len(b),'sha256':sha(b)});return b

def write(n,s):
 p=(L/n).resolve();assert p.is_relative_to(L);p.write_text(s)
def dump(n,x):write(n,json.dumps(x,ensure_ascii=False,indent=2)+'\n')
r=json.loads(read(L/'reservation.json')); prov=json.loads(read(L/'literal-provenance.json'))
# Exact explicit history list only; title/source aliases, never recursive body scans.
history=[]
for p in json.loads(read(L/'historical-results-allowlist.json')):
 if any(w in p.lower() for w in ['crown','transitive-bunkbed-formal-pi-r2']):continue
 p=pathlib.Path(p)
 if not p.is_file():continue
 b=read(p);txt=b.decode(errors='replace')
 for row in r['rows']:
  aliases=[row['title'],row['source_url']]
  hit=[a for a in aliases if a.casefold() in txt.casefold()]
  if hit:history.append({'path':str(p),'id':row['mathdb_id'],'aliases':hit,'depth':'exact completed results file alias match; not inherited disposition'})
dump('history-family-matches.json',history)
